<script setup lang="ts">
import type { ScreenComponent2D } from '@visualtwin/runtime-2d'
type Item = Extract<ScreenComponent2D, { type: 'screen.border' | 'screen.decoration' | 'screen.table' }>
const props = defineProps<{ item: Item }>()
const emit = defineEmits<{ change: [item: Item], error: [message: string], duplicate: [], remove: [] }>()
function change(fn: (item: Item) => void) { const item = JSON.parse(JSON.stringify(props.item)) as Item; fn(item); emit('change', item) }
function text(event: Event) { return (event.target as HTMLInputElement).value }
function number(event: Event) { return (event.target as HTMLInputElement).valueAsNumber }
function json(event: Event, key: 'columns' | 'rows') { try { const value = JSON.parse((event.target as HTMLTextAreaElement).value); change(item => { if (item.type === 'screen.table') item.props[key] = value }) } catch { emit('error', '表格配置须为合法 JSON') } }
</script>
<template><div class="property-form"><label>名称<input aria-label="2D 名称" :value="item.name" @change="change(i => i.name = text($event))"></label><label>类型<input :value="item.type" readonly></label><label><input aria-label="2D 显示" type="checkbox" :checked="item.visible" @change="change(i => i.visible = ($event.target as HTMLInputElement).checked)"> 显示组件</label><div class="layout-grid"><label v-for="field in (['x','y','width','height','zIndex'] as const)" :key="field">{{ { x:'X', y:'Y', width:'宽度', height:'高度', zIndex:'层级' }[field] }}<input type="number" :aria-label="`2D ${field}`" :value="item.layout[field]" @change="change(i => i.layout[field] = number($event))"></label></div><label>背景颜色<input aria-label="背景颜色" type="color" :value="item.style.background" @change="change(i => i.style.background = text($event))"></label><label>透明度<input aria-label="透明度" type="number" min="0" max="1" step="0.1" :value="item.style.opacity" @change="change(i => i.style.opacity = number($event))"></label>
<template v-if="item.type === 'screen.border' || item.type === 'screen.decoration'"><label>样式<select aria-label="装饰样式" :value="item.props.variant" @change="change(i => { if (i.type === 'screen.border') i.props.variant = text($event) as 'line' | 'corners' | 'glow'; else if (i.type === 'screen.decoration') i.props.variant = text($event) as 'line' | 'tech' | 'title' | 'dots' })"><template v-if="item.type === 'screen.border'"><option value="line">简洁线框</option><option value="corners">科技四角</option><option value="glow">发光标题</option></template><template v-else><option value="line">分隔线</option><option value="tech">科技线条</option><option value="title">标题装饰</option><option value="dots">光点</option></template></select></label><label>颜色<input aria-label="装饰颜色" type="color" :value="item.props.color" @change="change(i => { if (i.type !== 'screen.table') i.props.color = text($event) })"></label><label>线宽<input aria-label="装饰线宽" type="number" min="1" max="12" :value="item.props.thickness" @change="change(i => { if (i.type !== 'screen.table') i.props.thickness = number($event) })"></label><label v-if="item.type === 'screen.border'">背景透明度<input aria-label="边框背景透明度" type="number" min="0" max="1" step="0.1" :value="item.props.backgroundOpacity" @change="change(i => { if (i.type === 'screen.border') i.props.backgroundOpacity = number($event) })"></label><label v-if="item.type === 'screen.border'">标题<input aria-label="边框标题" :value="item.props.title" @change="change(i => { if (i.type === 'screen.border') i.props.title = text($event) })"></label><label v-else><input aria-label="垂直装饰" type="checkbox" :checked="item.props.vertical" @change="change(i => { if (i.type === 'screen.decoration') i.props.vertical = ($event.target as HTMLInputElement).checked })"> 垂直</label></template>
<template v-else><label>列定义（JSON）<textarea aria-label="表格列" rows="5" :value="JSON.stringify(item.props.columns, null, 2)" @change="json($event, 'columns')"></textarea></label><label>静态行（JSON）<textarea aria-label="表格行" rows="6" :value="JSON.stringify(item.props.rows, null, 2)" @change="json($event, 'rows')"></textarea></label><label v-for="field in (['headerHeight','rowHeight','fontSize','speed'] as const)" :key="field">{{ { headerHeight:'表头高度', rowHeight:'行高', fontSize:'字号', speed:'滚动速度（像素/秒）' }[field] }}<input type="number" :aria-label="`表格 ${field}`" :value="item.props[field]" @change="change(i => { if (i.type === 'screen.table') i.props[field] = number($event) })"></label><label v-for="field in (['color','headerBackground','rowBackground','alternateBackground'] as const)" :key="field">{{ { color:'字体颜色', headerBackground:'表头背景', rowBackground:'行背景', alternateBackground:'隔行背景' }[field] }}<input type="color" :aria-label="`表格 ${field}`" :value="item.props[field]" @change="change(i => { if (i.type === 'screen.table') i.props[field] = text($event) })"></label><label><input aria-label="暂停滚动" type="checkbox" :checked="item.props.paused" @change="change(i => { if (i.type === 'screen.table') i.props.paused = ($event.target as HTMLInputElement).checked })"> 暂停滚动</label></template><div class="object-actions"><button @click="emit('duplicate')">复制</button><button @click="emit('remove')">删除</button></div></div></template>
